/* charts.js: tiny inline-SVG charts (no library). All text put in the SVG is generated by the app, never user input. */
(function () {
  'use strict';
  var App = window.App;
  function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;'); }
  function wrap(w, h, inner, label) {
    return App.svg('<svg class="chart" viewBox="0 0 ' + w + ' ' + h + '" role="img" aria-label="' + esc(label) + '">' + inner + '</svg>');
  }
  var Chart = App.chart = {};
  /* bars: [{label, value}] */
  Chart.bars = function (items, o) {
    o = o || {}; var w = 320, h = 140, pl = 8, pb = 22, pt = 14, n = items.length, max = Math.max.apply(null, items.map(function (i) { return i.value; }).concat([o.min || 1]));
    var bw = (w - pl * 2) / n, inner = '<line class="grid" x1="0" x2="' + w + '" y1="' + (h - pb) + '" y2="' + (h - pb) + '"/>';
    items.forEach(function (it, i) {
      var bh = (h - pb - pt) * it.value / max, x = pl + i * bw + bw * 0.18;
      inner += '<rect class="bar" rx="3" x="' + x.toFixed(1) + '" y="' + (h - pb - bh).toFixed(1) + '" width="' + (bw * 0.64).toFixed(1) + '" height="' + Math.max(bh, it.value > 0 ? 2 : 0).toFixed(1) + '"/>' +
        '<text x="' + (pl + i * bw + bw / 2).toFixed(1) + '" y="' + (h - 8) + '" text-anchor="middle">' + esc(it.label) + '</text>' +
        (it.value > 0 ? '<text x="' + (pl + i * bw + bw / 2).toFixed(1) + '" y="' + (h - pb - bh - 4).toFixed(1) + '" text-anchor="middle">' + esc(it.text || it.value.toFixed(1)) + '</text>' : '');
    });
    return wrap(w, h, inner, o.label || 'Bar chart');
  };
  /* line: [{label, value}]; o.invert puts smaller values higher (pace); o.fmt formats y labels */
  Chart.line = function (pts, o) {
    o = o || {}; var w = 320, h = 150, pl = 36, pr = 10, pt = 14, pb = 22;
    if (pts.length < 2) return wrap(w, h, '<text x="' + w / 2 + '" y="' + h / 2 + '" text-anchor="middle">Not enough data yet</text>', o.label || 'Line chart');
    var vals = pts.map(function (p) { return p.value; }), lo = Math.min.apply(null, vals), hi = Math.max.apply(null, vals);
    if (hi - lo < 1e-9) { hi += 1; lo -= 1; }
    var padv = (hi - lo) * 0.1; lo -= padv; hi += padv;
    function X(i) { return pl + (w - pl - pr) * i / (pts.length - 1); }
    function Y(v) { var f = (v - lo) / (hi - lo); if (o.invert) f = 1 - f; return pt + (h - pt - pb) * (1 - f); }
    var fmt = o.fmt || function (v) { return v.toFixed(1); };
    var inner = '<line class="grid" x1="' + pl + '" x2="' + (w - pr) + '" y1="' + Y(hi) + '" y2="' + Y(hi) + '"/><line class="grid" x1="' + pl + '" x2="' + (w - pr) + '" y1="' + Y(lo) + '" y2="' + Y(lo) + '"/>' +
      '<text x="' + (pl - 4) + '" y="' + (Y(hi) + 3) + '" text-anchor="end">' + esc(fmt(hi)) + '</text><text x="' + (pl - 4) + '" y="' + (Y(lo) + 3) + '" text-anchor="end">' + esc(fmt(lo)) + '</text>';
    inner += '<path class="ln" d="' + pts.map(function (p, i) { return (i ? 'L' : 'M') + X(i).toFixed(1) + ' ' + Y(p.value).toFixed(1); }).join(' ') + '"/>';
    pts.forEach(function (p, i) { inner += '<circle class="dot" r="3" cx="' + X(i).toFixed(1) + '" cy="' + Y(p.value).toFixed(1) + '"/>'; });
    inner += '<text x="' + pl + '" y="' + (h - 6) + '">' + esc(pts[0].label) + '</text><text x="' + (w - pr) + '" y="' + (h - 6) + '" text-anchor="end">' + esc(pts[pts.length - 1].label) + '</text>';
    return wrap(w, h, inner, o.label || 'Line chart');
  };
  /* progress ring, frac 0..1, centre text */
  Chart.ring = function (frac, text, size, label) {
    size = size || 88; var r = 36, c = 2 * Math.PI * r; frac = Math.max(0, Math.min(1, frac || 0));
    var el = App.svg('<svg class="ring" width="' + size + '" height="' + size + '" viewBox="0 0 88 88" role="img" aria-label="' + esc(label || 'Progress') + '">' +
      '<circle class="bg" cx="44" cy="44" r="' + r + '" fill="none" stroke-width="8"/>' +
      '<circle class="fg" cx="44" cy="44" r="' + r + '" fill="none" stroke-width="8" stroke-linecap="round" stroke-dasharray="' + (c * frac).toFixed(1) + ' ' + c.toFixed(1) + '" transform="rotate(-90 44 44)"/>' +
      '<text x="44" y="50" text-anchor="middle" font-size="18">' + esc(text) + '</text></svg>');
    return el;
  };
  /* GPS route */
  Chart.route = function (pts, label) {
    var d = window.Gps.routePath(pts, 320, 220, 14);
    if (!d) return wrap(320, 220, '<text x="160" y="110" text-anchor="middle">Waiting for GPS…</text>', label || 'Route');
    var f = pts[0], l = pts[pts.length - 1];
    var a = window.Gps.routePath([f, f.lat === l.lat && f.lon === l.lon ? { lat: f.lat + 1e-9, lon: f.lon } : l], 320, 220, 14);
    return wrap(320, 220, '<path class="route" d="' + d + '"/>', label || 'Route map');
  };
})();
